// Generates tests/fixtures/crs/builtin_wkt_skeletons.txt (WP-12.2).
//
// Not part of the build: a developer runs it with the local PROJ whenever the
// built-in list changes or a PROJ data release changes something structural, and
// commits the result. The normaliser is shared with the test
// (tests/crs_wkt_skeleton.hpp), so a fixture can never disagree with the
// assertion because of normalisation drift.
//
//   c++ -std=c++20 -I engine/src -I engine/tests \
//       engine/tests/fixtures/crs/make_skeletons.cpp -lproj -o /tmp/make_skeletons
//   /tmp/make_skeletons > engine/tests/fixtures/crs/builtin_wkt_skeletons.txt
//
// Format: one line per CRS, `<epsg> <skeleton>`; '#' starts a comment.

#include <cstdio>
#include <string>
#include <vector>

#include <proj.h>

#include "crs_wkt_skeleton.hpp"

namespace {

// The curated code list, duplicated here because this tool must compile without
// the engine library. Keep in step with src/model/crs/builtin_crs.cpp.
const int kCodes[] = {
    4326, 4979, 4978,
    32601, 32602, 32603, 32604, 32605, 32606, 32607, 32608, 32609, 32610,
    32611, 32612, 32613, 32614, 32615, 32616, 32617, 32618, 32619,
    32701, 32702, 32703, 32704, 32705,
    4258, 25832, 3035,
    4269, 26911, 26914, 26919, 5070,
    7844, 7855,
    3006, 27700, 2056,
    4167, 2193,
    4674, 31983,
    4490, 4548,
    3857,
    4230,
};

}  // namespace

int main() {
    PJ_CONTEXT* ctx = proj_context_create();
    proj_log_level(ctx, PJ_LOG_NONE);
    const char* const options[] = {"MULTILINE=NO", nullptr};

    std::printf("# WKT2:2019 structural skeletons of the built-in list (M12 §4.6).\n");
    std::printf("# Generated by tests/fixtures/crs/make_skeletons.cpp; do not edit by hand.\n");
    std::printf("# Names, MEMBER/ID/USAGE/BBOX blocks are removed so the file is\n");
    std::printf("# identical on PROJ 9.4 and 9.9 (see tests/crs_wkt_skeleton.hpp).\n");
    std::printf("# <epsg> <skeleton>\n");

    for (int code : kCodes) {
        const std::string text = "EPSG:" + std::to_string(code);
        PJ* pj = proj_create(ctx, text.c_str());
        if (pj == nullptr || proj_is_crs(pj) == 0) {
            std::fprintf(stderr, "fatal: EPSG:%d is not a CRS in this PROJ\n", code);
            proj_destroy(pj);
            proj_context_destroy(ctx);
            return 1;
        }
        const char* wkt = proj_as_wkt(ctx, pj, PJ_WKT2_2019, options);
        if (wkt == nullptr) {
            std::fprintf(stderr, "fatal: EPSG:%d has no WKT2:2019 form\n", code);
            proj_destroy(pj);
            proj_context_destroy(ctx);
            return 1;
        }
        std::printf("%d %s\n", code, crs_fixture::wkt_skeleton(wkt).c_str());
        proj_destroy(pj);
    }
    proj_context_destroy(ctx);
    return 0;
}
